import queue


def accepted(cap: int, xs: list[int]) -> int:
    """Count how many elements of xs a bounded queue accepts before it is full.

    Creates a queue.Queue holding at most `cap` integers and tries to put each
    element of xs in order without blocking (put_nowait). Nothing is ever
    taken from the queue. The first put that finds the queue full stops the
    process, and the number of puts accepted up to that point is returned.

    If cap <= 0 the queue can hold nothing, so the result is 0 (this differs
    from queue.Queue, where maxsize <= 0 means unbounded).
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_stops_when_full() -> None:
    assert accepted(3, [10, 20, 30, 40, 50]) == 3


def test_cap_larger_than_input() -> None:
    assert accepted(10, [1, 2, 3]) == 3


def test_cap_equals_length() -> None:
    assert accepted(4, [1, 2, 3, 4]) == 4


def test_empty_input() -> None:
    assert accepted(5, []) == 0


def test_cap_one() -> None:
    assert accepted(1, [7, 8, 9]) == 1


def test_zero_capacity_accepts_nothing() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_negative_capacity_accepts_nothing() -> None:
    assert accepted(-2, [1, 2, 3]) == 0


def test_duplicates_are_all_accepted() -> None:
    assert accepted(3, [5, 5, 5, 5]) == 3


def test_does_not_depend_on_values() -> None:
    assert accepted(2, [-1, 0, 10**9]) == 2
